*/
func getStudentInfo(xmlData, username, password string) (string, string, string) {
	// Parse the XML data
	doc := xmltree.NewXMLTree(bytes.NewBufferString(xmlData))

	// Construct the XPath query to find the student by username and password
	// We need to escape the username and password for use in the XPath query
	escapedUsername := strings.ReplaceAll(username, "'", "''")
	escapedPassword := strings.ReplaceAll(password, "'", "''")

	xpathQuery := `//student[username/text()='` + escapedUsername + `' and password/text()='` + escapedPassword + `']`

	// Execute the XPath query
	nodes, err := goxpath.Evaluate(doc, xpathQuery)
	if err != nil {
		// Handle error gracefully, return empty strings
		return "", "", ""
	}

	// Check if a student was found
	if len(nodes) == 0 {
		return "", "", ""
	}

	// Assuming only one student matches the criteria
	studentNode := nodes[0]

	var name, age, citizenship string

	// Extract student information
	nameNode, err := studentNode.SelectNode("name")
	if err == nil && nameNode != nil {
		name = nameNode.Value()
	}

	ageNode, err := studentNode.SelectNode("age")
	if err == nil && ageNode != nil {
		age = ageNode.Value()
	}

	citizenshipNode, err := studentNode.SelectNode("citizenship")
	if err == nil && citizenshipNode != nil {
		citizenship = citizenshipNode.Value()
	}

	return name, age, citizenship
}
