char *get_user(sqlite3 *db, const char *username, const char *password) {
    sqlite3_stmt *stmt;
    char *user_info = NULL;
    int rc;

    // Construct the SQL query using parameterized queries to prevent SQL injection.
    const char *sql = "SELECT userInfo FROM users WHERE username = ? AND password = ?";

    rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        // Handle error if necessary, but for this function, we'll just return NULL.
        return NULL;
    }

    // Bind the username and password to the prepared statement.
    sqlite3_bind_text(stmt, 1, username, -1, SQLITE_STATIC);
    sqlite3_bind_text(stmt, 2, password, -1, SQLITE_STATIC);

    // Execute the query.
    rc = sqlite3_step(stmt);

    if (rc == SQLITE_ROW) {
        // User found, retrieve the userInfo.
