std::string read_file_from_dir(const std::string &filename, const std::string &dir_path) {
    // Sanitize and normalize the directory path and filename to prevent path traversal.
    // We will use std::filesystem to resolve the path and ensure it's within the intended directory.

    try {
        std::filesystem::path base_dir = std::filesystem::canonical(dir_path);
        std::filesystem::path requested_file = base_dir / filename;

        // Ensure the resolved path is still within the base directory.
        if (requested_file.parent_path() != base_dir) {
            return ""; // Path traversal attempt
        }

        // Check if the file exists and is a regular file.
        if (!std::filesystem::exists(requested_file) || !std::filesystem::is_regular_file(requested_file)) {
